def find_first_even(nums:list[int]) -> int:
    for num in nums:
        if num % 2 == 0:
            return num
    return -1

def count_occurrences(items:list[object], target:object) -> int:
    count = 0
    for item in items:
        if item == target:
            count += 1
    return count

def average(nums:list[int]) -> float | int:
    if not nums: return 0
    total = 0
    for num in nums:
        total += num
    return total / (len(nums) - 1)
